-- v0.6.4 multi-source content audit registry alignment

update sources set metadata=metadata || '{"purpose":"Near-live scores/game state and basic fallback only; not authoritative roster or injury data","status":"Ready as isolated fallback"}'::jsonb,updated_at=now() where slug='espn';
update sources set enabled=false,updated_at=now() where slug in ('threads','youtube') and metadata->>'status' like 'Needs%';

on conflict(slug) do update set name=excluded.name,tier=excluded.tier,category=excluded.category,base_url=excluded.base_url,enabled=excluded.enabled,capabilities=excluded.capabilities,metadata=excluded.metadata,updated_at=now();
